3	import java.util.List;
4	
5	/**
6	 * 灌区配水 API 请求/响应契约。水量在 API 层一律使用十进制字符串（单位立方米，最多 3 位小数），
7	 * 时间使用 ISO-8601 UTC 字符串。
8	 */
9	public final class Dtos {
10	
11	    private Dtos() {
12	    }
13	
14	    /** 创建供水窗口命令。 */
15	    public record CreateWindowRequest(String commandKey, String windowKey, String channelId,
16	                                      String startUtc, String endUtc, String plannedVolume) {
17	    }
18	
19	    /** 供水窗口视图；activeCurtailmentVolume 为 null 表示无生效限供。 */
20	    public record WindowResponse(long id, String windowKey, String channelId, String startUtc, String endUtc,
21	                                 String plannedVolume, String activeCurtailmentVolume, String availableTotal,
22	                                 String createdUtc) {
23	    }
24	
25	    /** 提交配水申请命令；申请人由 X-Actor-Id 请求头提供。 */
26	    public record SubmitAllocationRequest(String commandKey, String allocationKey, Long windowId,
27	                                          String userId, String amount) {
28	    }
29	
30	    /** 配水申请视图。状态：REQUESTED / APPROVED / CANCELLED。 */
